mapper.update:
update t_payment_order
set refund_frozen_amount = refund_frozen_amount + #{amount}, update_time = CURRENT_TIMESTAMP
where payment_no = #{paymentNo}
and paid_amount - refunded_amount - refund_frozen_amount >= #{amount}

update t_payment_order
set refund_frozen_amount = refund_frozen_amount - #{amount},
refunded_amount = refunded_amount + #{amount},
update_time = CURRENT_TIMESTAMP
where payment_no = #{paymentNo}
and refund_frozen_amount >= #{amount}

update t_payment_order
set status = 'CLOSED', update_time = CURRENT_TIMESTAMP
where order_no = #{orderNo}
and payment_no != #{paymentNo}
and status in ('CREATED', 'PAYING')
